1400	// ---------------------------------------------------------------------------
1401	// GET /api/projects/:slug/chunks
1402	// ---------------------------------------------------------------------------
1403	
1404	/** Filename allowlist pattern for chunk files: only alphanumeric, hyphens, underscores + .jsonl */
1405	const CHUNK_FILENAME_RE = /^[A-Za-z0-9_-]+\.jsonl$/;
1406	
1407	/** Parse pattern for chunk filenames: `{WP_ID}-{stage}-r{N}.jsonl` or `project-{stage}-r{N}.jsonl` */
1408	const CHUNK_PARSE_RE = /^(WP-\d+|project)-(.+)-r(\d+)\.jsonl$/;
1409	
1410	/**
1411	 * Parsed representation of a single chunk file.
1412	 * Derived from the filename convention `{WP_ID}-{stage}-r{N}.jsonl`
1413	 * or `project-{stage}-r{N}.jsonl` for project-level (PM/Synthesis) chunks.
1414	 */
1415	export interface ChunkEntry {
1416	  filename: string;
1417	  wp_id: string;
1418	  stage: string;
1419	  revision: number;
1420	}
1421	
1422	/** Parses a chunk filename into a structured entry. Handles both `WP-\d+` and `project` prefixes. */
1423	function parseChunkFilename(filename: string): ChunkEntry {
1424	  const m = CHUNK_PARSE_RE.exec(filename);
1425	  if (m) {
1426	    return { filename, wp_id: m[1]!, stage: m[2]!, revision: parseInt(m[3]!, 10) };
1427	  }
1428	  return { filename, wp_id: '', stage: '', revision: 0 };
1429	}
1430	
1431	/**
1432	 * Returns an array of structured chunk entries from the project's
1433	 * orchestrator/chunks/ directory. Each entry includes the filename plus
1434	 * the wp_id and stage parsed from the filename convention
1435	 * `{WP_ID}-{stage}-r{N}.jsonl`.
1436	 *
1437	 * @param ledgerRoot  Root directory containing all project ledger folders.
1438	 * @param slug        Project slug — validated via assertSafeSlug().
1439	 * @param wpId        Optional WP ID prefix filter (e.g. 'WP-001').
1440	 *                    When provided, only filenames starting with '{wpId}-' are returned.
1441	 * @param repoName    Repository namespace. Used to namespace the storage path.
1442	 * @returns           Sorted array of ChunkEntry objects, or [] when the directory
1443	 *                    is absent (no error thrown).
1444	 */
1445	export async function handleListChunks(
1446	  ledgerRoot: string,
1447	  slug: string,
1448	  wpId?: string,
1449	  repoName?: string
1450	): Promise<ChunkEntry[]> {
1451	  assertSafeSlug(slug);
1452	
1453	  const store = await resolveProjectStore(ledgerRoot, slug, repoName);
1454	  const chunksDir = join(store.storageDir, CHUNKS_DIR);
1455	
1456	  let entries: string[];
1457	  try {
1458	    entries = await readdir(chunksDir);
1459	  } catch (err: unknown) {
1460	    // Directory absent — return empty array rather than throwing.
1461	    if (isNodeError(err) && (err.code === 'ENOENT' || err.code === 'ENOTDIR')) {
1462	      return [];
1463	    }
1464	    throw err;
1465	  }
1466	
1467	  // Filter to .jsonl files only.
1468	  let filenames = entries.filter((f) => f.endsWith('.jsonl'));
1469	
1470	  // Optional WP ID prefix filter — validate the value before using it.
1471	  if (wpId) {
1472	    if (!WP_ID_RE.test(wpId)) {
1473	      // Invalid wpId (e.g. injection attempt or malformed value): return empty list.
1474	      return [];
1475	    }
1476	    const prefix = `${wpId}-`;
1477	    filenames = filenames.filter((f) => f.startsWith(prefix));
1478	  }
1479	
1480	  return filenames.sort().map(parseChunkFilename);
1481	}
1482	
1483	// ---------------------------------------------------------------------------
1484	// GET /api/projects/:slug/chunks/:filename
1485	// ---------------------------------------------------------------------------
1486	
1487	/**
1488	 * Returns the raw JSONL content of a single chunk file.
1489	 *
1490	 * Security:
1491	 * - `slug` is validated via assertSafeSlug().
1492	 * - `filename` must match CHUNK_FILENAME_RE (alphanumeric + hyphens/underscores + .jsonl).
1493	 * - Resolved path must be inside the project's orchestrator/chunks/ directory (defence-in-depth).
1494	 *
1495	 * @param ledgerRoot  Root directory containing all project ledger folders.
