1204	    }
1205	    return text + '\n';
1206	  }
1207	
1208	  // --- Dual-namespace: labelled sections ---
1209	  const mainMessages = nsMap.get('') ?? [];
1210	  const outerText = extractTextFromMessages(mainMessages);
1211	
1212	  const innerTexts: string[] = [];
1213	  for (const [nsKey, messages] of nsMap.entries()) {
1214	    if (nsKey === '') continue;
1215	    innerTexts.push(extractTextFromMessages(messages));
1216	  }
1217	
1218	  // If all sections are empty, return the standard empty sentinel.
1219	  if (!outerText && innerTexts.every(t => !t)) {
1220	    return '*No dialogue recorded.*\n';
1221	  }
1222	
1223	  const sections: string[] = [];
1224	  sections.push('## Outer Agent\n\n' + (outerText || '*No dialogue recorded.*'));
1225	  for (const innerText of innerTexts) {
1226	    sections.push('## Inner Agent\n\n' + (innerText || '*No dialogue recorded.*'));
1227	  }
1228	
